from .common import code, case

def d(day,title,prompt,starter,cases,**kwargs):
    return code(day,'D',title,prompt+'\n\nВ notes.md найдите и объясните причины проблем; исправьте код и пройдите тесты. Не предполагается заранее известное число дефектов. Если фрагмент корректен, объясните почему и сохраните его.',cases,starter=starter,**kwargs)


d(2,'Размер буфера','clone_text(const char*) возвращает независимый new[]-буфер с полным содержимым, включая ноль. nullptr → invalid_argument.', '#include <cstring>\nchar* clone_text(const char* p){auto* r=new char[std::strlen(p)];std::strcpy(r,p);return r;}\n',[case('Содержимое и ноль','char* p=clone_text("abc"); CHECK(std::strcmp(p,"abc")==0); delete[] p;'),case('Пустой и nullptr','char* p=clone_text(""); CHECK(p[0]==0); delete[] p; expect_throw<std::invalid_argument>([]{clone_text(nullptr);});','negative')],memory=True,unsafeStarter=True)
d(2,'Освобождение ресурса','dispose(int*&) освобождает массив new[] и обнуляет исходный указатель. Повторное освобождение допустимо.', '#include <cstdlib>\nvoid dispose(int*& p){std::free(p);}\n',[case('Обнуление и повторный вызов','int* p=new int[3]; dispose(p); CHECK(p==nullptr); dispose(p);')],memory=True,unsafeStarter=True)
TEXT='#include <cstring>\nclass Text{char* data_;public:explicit Text(const char* s){data_=new char[std::strlen(s)+1];std::strcpy(data_,s);}~Text(){delete[] data_;}char& operator[](unsigned i){return data_[i];}const char* c_str()const{return data_;}};\n'
d(2,'Копии владельца','Исправьте Text: правило трёх, независимое владение, nullptr → invalid_argument, индекс>=strlen → out_of_range. Сохраните существующие имена методов.',TEXT,[case('Копирование','Text a("abc"); Text b(a); b[0]=char(120); CHECK(std::strcmp(a.c_str(),"abc")==0);'),case('Присваивание','Text a("old"),b("new"); a=b; b[0]=char(88); CHECK(std::strcmp(a.c_str(),"new")==0); a=a; CHECK(std::strcmp(a.c_str(),"new")==0);')],memory=True,unsafeStarter=True)
d(2,'Порядок замены','replace_copy(char*&,const char*) заменяет владеющий new[]-буфер независимой копией. Источник может быть target+1, nullptr запрещён. При ошибке старый буфер сохраняется.', '#include <cstring>\nvoid replace_copy(char*& p,const char* s){delete[] p;p=new char[std::strlen(s)+1];std::strcpy(p,s);}\n',[case('Самоалиасинг','char* p=new char[5]{char(116),char(101),char(115),char(116),0}; replace_copy(p,p+1); CHECK(std::strcmp(p,"est")==0); delete[] p;'),case('Отказ выделения','char* p=new char[4]{char(111),char(108),char(100),0}; mastery_memory::fail_after=0; bool caught=false; try{replace_copy(p,"new text");}catch(const std::bad_alloc&){caught=true;} mastery_memory::fail_after=-1; CHECK(caught && std::strcmp(p,"old")==0); delete[] p;','exception')],memory=True,unsafeStarter=True)
d(2,'Проверка nullptr','text_length(const char*) возвращает strlen, nullptr → invalid_argument до чтения памяти.', '#include <cstring>\n#include <stdexcept>\nstd::size_t text_length(const char* p){auto n=std::strlen(p);if(!p)throw std::invalid_argument("null");return n;}\n',[case('Длина','CHECK(text_length("abc")==3 && text_length("")==0);'),case('nullptr','expect_throw<std::invalid_argument>([]{text_length(nullptr);});','negative')],memory=True,unsafeStarter=True)
d(2,'Арифметика size_t','checked_sum(a,b) возвращает a+b+1 типа size_t. Переполнение → length_error до выполнения сложения.', '#include <cstddef>\nstd::size_t checked_sum(std::size_t a,std::size_t b){return a+b+1;}\n',[case('Обычный размер','CHECK(checked_sum(2,3)==6);'),case('Границы size_t','const auto m=std::numeric_limits<std::size_t>::max(); expect_throw<std::length_error>([&]{checked_sum(m,0);}); expect_throw<std::length_error>([&]{checked_sum(m-1,1);});','negative')])
d(2,'Сдвиг с нулём','erase_prefix(char*,size_t) удаляет первые count символов C-строки на месте. nullptr → invalid_argument; count>strlen → out_of_range без изменения.', '#include <cstring>\nvoid erase_prefix(char* s,std::size_t n){std::memmove(s,s+n,std::strlen(s)-n);}\n',[case('Правильный ноль','char s[]="abcdef"; erase_prefix(s,2); CHECK(std::strcmp(s,"cdef")==0); erase_prefix(s,4); CHECK(s[0]==0);'),case('Ошибки','char s[]="ab"; expect_throw<std::out_of_range>([&]{erase_prefix(s,3);}); CHECK(std::strcmp(s,"ab")==0); expect_throw<std::invalid_argument>([]{erase_prefix(nullptr,0);});','negative')],memory=True,unsafeStarter=True)
d(2,'Самоконкатенация','append(char*& target,const char* other) добавляет other к владеющему target. Поддержите other==target и указатель внутрь target. nullptr → invalid_argument; сильная гарантия, переполнение → length_error.', '#include <cstring>\nvoid append(char*& p,const char* q){auto n=std::strlen(p)+std::strlen(q);char* r=new char[n+1];std::strcpy(r,p);delete[] p;std::strcat(r,q);p=r;}\n',[case('s += s','char* s=new char[3]{char(97),char(98),0}; append(s,s); CHECK(std::strcmp(s,"abab")==0); delete[] s;'),case('Внутренний указатель','char* s=new char[4]{char(97),char(98),char(99),0}; append(s,s+1); CHECK(std::strcmp(s,"abcbc")==0); delete[] s;')],memory=True,unsafeStarter=True)

d(3,'T против T*','value(const T*) возвращает копию T, nullptr → invalid_argument.', 'template<class T> T value(const T* p){return p;}\n',[case('Типы','const int x=3; const double d=2.5; CHECK(value(&x)==3 && value(&d)==2.5);'),case('nullptr','expect_throw<std::invalid_argument>([]{value<int>(nullptr);});','negative')])
d(3,'Конфликт вывода','Сохраните однотипный maximum. Исправьте mixed() так, чтобы явно выбрать double и вернуть максимум 2.5 и 3.', 'template<class T>T maximum(T a,T b){return a<b?b:a;}\ndouble mixed(){return maximum(2.5,3);}\n',[case('Вызов','CHECK(mixed()==3.0);')])
d(3,'Потеря дробной части','sum(A,B) должен возвращать тип a+b и сохранять дробь в обеих позициях.', 'template<class A,class B>B sum(A a,B b){return static_cast<B>(a+b);}\n',[case('Разные типы','CHECK(sum(2.5,3)==5.5 && sum(3,2.5)==5.5);')],checks='static_assert(std::is_same_v<decltype(sum(2.5,3)),double>);')
d(3,'Запись специализации','Сохраните общий kind(T)==1 и полную специализацию для int с результатом 2.', 'template<class T>int kind(T){return 1;}\ntemplate<int>int kind<int>(int){return 2;}\n',[case('Выбор типа','CHECK(kind(1)==2 && kind(1.0)==1);')])
d(3,'Сравнение адресов','maximum(const char*,const char*) возвращает лексикографический максимум (при равенстве первый), nullptr → invalid_argument.', 'const char* maximum(const char* a,const char* b){return a>b?a:b;}\n',[case('Порядок содержимого','char a[][8]={"z","aa"}; CHECK(maximum(a[0],a[1])==a[0]); CHECK(maximum(a[1],a[0])==a[0]);'),case('nullptr','expect_throw<std::invalid_argument>([]{maximum(nullptr,"x");});','negative')])
d(3,'Полнота return','abs_value(T) возвращает модуль. В тестах только представимые значения целых и double, минимальный int исключён.', 'template<class T>T abs_value(T x){if(x<0)return -x;}\n',[case('Обе ветви','CHECK(abs_value(-3)==3 && abs_value(3)==3 && abs_value(0)==0); CHECK(abs_value(-2.5)==2.5);')])
d(3,'Константный аргумент','read(const T&) возвращает копию значения, принимает константные и временные объекты.', 'template<class T>T read(T& x){return x;}\n',[case('Все категории','const int x=3; CHECK(read(x)==3 && read(4)==4); CHECK(read(2.5)==2.5);')])
d(3,'Тип исключения','at(const T*,size_t,size_t) возвращает const T&. nullptr → invalid_argument, неверный индекс → out_of_range.', '#include <cstddef>\n#include <stdexcept>\ntemplate<class T>const T& at(const T* a,std::size_t n,std::size_t i){if(!a||i>=n)throw std::runtime_error("bad");return a[i];}\n',[case('Ссылка','int a[]={2,3}; CHECK(&at(a,2,1)==&a[1]);'),case('Разные причины','expect_throw<std::invalid_argument>([]{at<int>(nullptr,0,0);}); int a[]={2}; expect_throw<std::out_of_range>([&]{at(a,1,1);});','negative')])

d(4,'Область шаблона','Box<T>::get() const возвращает value_. Исправьте определение за классом.', 'template<class T>class Box{T value_{};public:T get()const;};\ntemplate<class T>T Box::get()const{return value_;}\n',[case('Два типа','CHECK(Box<int>{}.get()==0 && Box<double>{}.get()==0.0);')])
d(4,'Параметр по умолчанию','Capacity<T,N=8>::size возвращает N. Исправьте внешнее определение.', 'template<class T,int N=8>struct Capacity{int size()const;};\ntemplate<class T,int N=8>int Capacity<T,N>::size()const{return N;}\n',[case('Разные ёмкости','CHECK(Capacity<int>{}.size()==8); CHECK((Capacity<double,3>{}.size()==3));')])
d(4,'Зависимая база','Derived<T> наследует Base<T> и возвращает protected value_ через get() const.', 'template<class T>struct Base{protected:T value_{};};\ntemplate<class T>struct Derived:Base{T get()const{return value_;}};\n',[case('Наследование','CHECK(Derived<int>{}.get()==0); CHECK((std::is_base_of_v<Base<int>,Derived<int>>));')])
d(4,'Не реализован контракт','Derived должен быть конкретным наследником Base и возвращать 7 из const-метода get().', 'struct Base{virtual ~Base()=default;virtual int get()const=0;};\nstruct Derived:Base{int get(){return 7;}};\n',[case('Полиморфный const-вызов','const Derived d; const Base& b=d; CHECK(b.get()==7);')])
d(4,'Уничтожение через базу','Сделайте удаление Derived через Base* корректным. Derived(int& count) увеличивает count при уничтожении.', 'struct Base{~Base()=default;};\nstruct Derived:Base{int& count;explicit Derived(int& n):count(n){}~Derived(){++count;}};\n',[case('Виртуальный деструктор','int n=0; Base* p=new Derived(n); delete p; CHECK(n==1);')],checks='static_assert(std::has_virtual_destructor_v<Base>);',memory=True,unsafeStarter=True)
LIST='#include <cstddef>\nclass Stack{struct Node{int value;Node* next;};Node* head_=nullptr;public:Stack()=default;Stack(const Stack&)=delete;Stack& operator=(const Stack&)=delete;void push(int v){head_=new Node{v,head_};}bool pop(int& v){if(!head_)return false;v=head_->value;delete head_;head_=head_->next;return true;}~Stack(){while(head_){Node* n=head_->next;delete head_;head_=n;}}};\n'
d(4,'Обновление головы','Stack::push/pop должны реализовывать LIFO. pop пустого стека возвращает false, сохраняя аргумент.',LIST,[case('LIFO','Stack s; s.push(1); s.push(2); int v=0; CHECK(s.pop(v) && v==2); CHECK(s.pop(v) && v==1); CHECK(!s.pop(v) && v==1);')],memory=True,unsafeStarter=True)
d(4,'Полная очистка','Stack должен освобождать все узлы. Добавьте правильный деструктор; копирование остаётся запрещённым.',LIST.replace('delete head_;head_=head_->next;', 'Node* old=head_;head_=head_->next;delete old;').replace('~Stack(){while(head_){Node* n=head_->next;delete head_;head_=n;}}','~Stack(){delete head_;}'),[case('Несколько узлов','for(int i=0;i<5;++i){Stack s; for(int j=0;j<10;++j)s.push(j);}'),case('Пустой объект','Stack s; int v=8; CHECK(!s.pop(v) && v==8);','boundary')],memory=True,unsafeStarter=True)
d(4,'Проверка динамического типа','as_derived(Base*) возвращает Derived* или nullptr. Разрешён nullptr-вход; неверный динамический тип не должен давать указатель Derived.', 'struct Base{virtual ~Base()=default;};struct Derived:Base{};\nDerived* as_derived(Base* p){return static_cast<Derived*>(p);}\n',[case('Успех и неудача','Derived d; Base b; CHECK(as_derived(&d)==&d && as_derived(&b)==nullptr && as_derived(nullptr)==nullptr);')])

EXAM=[
('Владеющий буфер','Owner(const char*) владеет независимой строкой; c_str() const возвращает её. Добавьте безопасное копирование и присваивание, nullptr → invalid_argument.','''#include <cstring>
struct Owner{char* p;explicit Owner(const char* s){p=new char[std::strlen(s)+1];std::strcpy(p,s);}~Owner(){delete p;}const char* c_str()const{return p;}};
''',[case('Копии и освобождение','Owner a("test"); Owner b(a); CHECK(a.c_str()!=b.c_str()); CHECK(std::strcmp(b.c_str(),"test")==0); Owner c(""); c=b; c=c; CHECK(std::strcmp(c.c_str(),"test")==0);')],True),
('Доступ к const','View[0] возвращает const int& при const View и int& иначе. Индексы вне 0 → out_of_range.','''#include <cstddef>
struct View{int data=4; int& operator[](std::size_t)const{return const_cast<int&>(data);}};
''',[case('Тип и доступ','View v; v[0]=9; const auto& c=v; CHECK(c[0]==9); CHECK((std::is_same_v<decltype(c[0]),const int&>)); expect_throw<std::out_of_range>([&]{(void)c[1];});')],False),
('Общий минимум','min_value(T,T) по значению использует только <. Проверьте корректность фрагмента на равных, отрицательных и дробных значениях.','template<class T>T min_value(T a,T b){return b<a?b:a;}\n',[case('Контракт','CHECK(min_value(2,2)==2 && min_value(-4,2)==-4 && min_value(2.5,1.5)==1.5);')],False),
('Нарушение инварианта','Counter имеет private size_=0; remove() при нуле бросает out_of_range, иначе уменьшает. add() увеличивает; size() const возвращает size_t.','''#include <cstddef>
class Counter{std::size_t size_=0;public:void add(){++size_;}void remove(){--size_;}std::size_t size()const{return size_;}};
''',[case('Граница','Counter c; expect_throw<std::out_of_range>([&]{c.remove();}); CHECK(c.size()==0); c.add(); c.remove(); CHECK(c.size()==0);')],False),
('Срезка исключения','guard(void(*)()) возвращает e.what() для любого std::exception, пустую строку при успехе.','''#include <exception>
#include <string>
std::string guard(void(*fn)()){try{fn();return "";}catch(std::exception e){return e.what();}}
''',[case('Динамический тип','CHECK(guard(+[]{throw std::out_of_range("range");})=="range"); CHECK(guard(+[]{})=="");')],False),
('Шаблонный внешний метод','Counter<T>::get() const возвращает value_ типа T, инициализированное нулём.','template<class T>class Counter{T value_{};public:T get()const;};\nT Counter<T>::get()const{return value_;}\n',[case('Подстановка','CHECK(Counter<int>{}.get()==0 && Counter<double>{}.get()==0.0);')],False),
('Транзакция','replace_copy(char*&,const char*) поддерживает алиасинг, nullptr → invalid_argument, сохраняет старый ресурс при bad_alloc.','''#include <cstring>
void replace_copy(char*& p,const char* s){delete[] p;p=new char[std::strlen(s)+1];std::strcpy(p,s);}
''',[case('Алиасинг','char* p=new char[4]{char(97),char(98),char(99),0}; replace_copy(p,p); CHECK(std::strcmp(p,"abc")==0); delete[] p;'),case('Отказ','char* p=new char[2]{char(97),0}; mastery_memory::fail_after=0; bool caught=false; try{replace_copy(p,"bbb");}catch(const std::bad_alloc&){caught=true;} mastery_memory::fail_after=-1; CHECK(caught && p[0]==char(97)); delete[] p;','exception')],True),
('Полиморфное уничтожение','Derived(int& n) увеличивает n при уничтожении через Base*. Проверьте все аспекты контракта.','struct Base{virtual ~Base()=default;};struct Derived:Base{int& n;explicit Derived(int& v):n(v){}~Derived()override{++n;}};\n',[case('Удаление','int n=0; Base* p=new Derived(n); delete p; CHECK(n==1);')],True),
('Неожиданная мутация','Value::operator+ создаёт независимый результат, оба операнда const допустимы.','struct Value{int n;Value& operator+(const Value& r){n+=r.n;return *this;}};\n',[case('Неизменность','const Value a{4},b{7}; auto c=a+b; CHECK(c.n==11 && a.n==4 && b.n==7);')],False),
('Выбор преобразования','check(Base&) возвращает Derived& или бросает bad_cast, без UB.','struct Base{virtual ~Base()=default;};struct Derived:Base{};\nDerived& check(Base& b){return static_cast<Derived&>(b);}\n',[case('Успех и отказ','Derived d; Base b; CHECK(&check(d)==&d); expect_throw<std::bad_cast>([&]{check(b);});')],False),
]
for title,prompt,starter,cases,memory in EXAM:
    d(5,'Review · '+title,prompt,starter,cases,memory=memory,unsafeStarter=memory,tags=['Code review','Dynamic memory' if memory else 'Синтаксис'])
